#include <stdio.h>

#define MOD 1000000007LL

long long checkRecord(int n) {
    long long dp[2][3] = {{1,0,0},{0,0,0}};
    for (int day = 0; day < n; ++day) {
        long long ndp[2][3] = {{0,0,0},{0,0,0}};
        for (int a = 0; a < 2; ++a) {
            for (int l = 0; l < 3; ++l) {
                long long v = dp[a][l];
                if (v == 0) continue;
                ndp[a][0] = (ndp[a][0] + v) % MOD;
                if (l < 2) ndp[a][l + 1] = (ndp[a][l + 1] + v) % MOD;
                if (a == 0) ndp[1][0] = (ndp[1][0] + v) % MOD;
            }
        }
        for (int a = 0; a < 2; ++a) for (int l = 0; l < 3; ++l) dp[a][l] = ndp[a][l];
    }
    long long ans = 0;
    for (int a = 0; a < 2; ++a) for (int l = 0; l < 3; ++l) ans = (ans + dp[a][l]) % MOD;
    return ans;
}

