                if (l < 2) ndp[a][l + 1] = (ndp[a][l + 1] + v) % MOD;
                if (a === 0) ndp[1][0] = (ndp[1][0] + v) % MOD;
            }
        }
        dp = ndp;
    }
    let ans = 0;
    for (const row of dp) for (const v of row) ans = (ans + v) % MOD;
    return ans;
}

